export type SiteCategory =
  | "传统教育基地"
  | "实践教育基地"
  | "文化教育基地"
  | "思想政治教育基地"
  | "名人故居"
  | "组织与机关"
  | "历史事件"
  | "民盟前史"
  | "英烈纪念"
  | "教育与校园";

export type Site = {
  id: string;
  name: string;
  category: SiteCategory;
  secondaryCategories?: SiteCategory[];
  district: string;
  address: string;
  old?: string;
  year: string;
  hook: string;
  story: string;
  anchor: string;
  people: string[];
  image?: string;
  imageAlt?: string;
  featured?: boolean;
  chapters?: { title: string; text: string }[];
  facts?: string[];
  architecture?: { title: string; text: string }[];
};

