  "huang-arrest": {
    facts: ["黄炎培次子", "哈佛大学经济学硕士", "1949年5月12日在404室被捕"],
    chapters: [
      { title: "一个金融专业者的地下工作", text: "黄竞武以中央银行稽核专员身份团结金融界、工商界人士，收集“四行两局”金融情报；中央银行404办公室、建国中路联络点和川沙掩护点构成工作网络。" },
      { title: "为什么阻止转运金银", text: "上海解放前夕，国民党当局企图转运中央银行金库财物。黄竞武参与组织职工抵制，担忧接管一座空城将无法养活数百万市民。金融情报工作因此直接关系城市能否平稳交接。" },
      { title: "明知危险仍选择留下", text: "同志曾安排他去苏州或川沙避险，他拒绝离开，认为越到紧要关头越要坚守岗位。5月12日上午，他在404办公室被捕。" },
    ],
  },
